// downloads.manorama.xyz — the public installer host *and* the release
// history, backed by the manorama-downloads R2 bucket. Objects live under
// v<semver>/ keys plus latest.json (the mutable pointer the platform
// shortcuts resolve through) and history.json (per-tag notes generated by
// scripts/build-download-history.mjs). Shipping a release is an upload +
// pointer bump + history refresh, never a deploy. The page carries the
// homepage's chrome — wordmark, nav, theme, footer — so the download
// surface reads as part of the same product.

export const DOWNLOAD_HOST = 'downloads.manorama.xyz'
const SITE = 'https://manorama.xyz'
const REPO = 'https://github.com/thecont1/manorama'

export type DownloadsEnv = { DOWNLOADS?: R2Bucket }

type LatestManifest = {
  version: string
  released?: string
  assets: { mac?: string; windows?: string; linux?: string; all?: string[] }
}

type HistoryHighlight = { sha: string; subject: string; url?: string }
type HistoryRelease = {
  version: string
  tag?: string
  date?: string
  commits?: number
  highlights?: HistoryHighlight[]
}
type HistoryManifest = { releases: HistoryRelease[] }

const PLATFORMS = new Set(['mac', 'windows', 'linux'])
const OBJECT_KEY = /^v\d+\.\d+\.\d+\/[\w.-]+$/
const ASSET_KEY = /^assets\/[\w-]+\/[\w.-]+$/
const MANIFEST_PATHS = new Set(['latest.json', 'history.json'])

export const isDownloadHost = (hostname: string) => hostname === DOWNLOAD_HOST

const latestManifest = async (env: DownloadsEnv): Promise<LatestManifest | null> => {
  if (!env.DOWNLOADS) return null
  const object = await env.DOWNLOADS.get('latest.json')
  if (!object) return null
  try {
    return (await object.json()) as LatestManifest
  } catch {
    return null
  }
}

const historyManifest = async (env: DownloadsEnv): Promise<HistoryManifest | null> => {
  if (!env.DOWNLOADS) return null
  const object = await env.DOWNLOADS.get('history.json')
  if (!object) return null
  try {
    const data = (await object.json()) as HistoryManifest
    if (!Array.isArray(data?.releases)) return null
    return {
      releases: data.releases.filter(
        (release): release is HistoryRelease =>
          typeof release?.version === 'string' && /^\d+\.\d+\.\d+$/.test(release.version),
      ),
    }
  } catch {
    return null
  }
}

const escapeHtml = (value: string) =>
  value.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

