const page = (title: string, body: string): Response =>
  new Response(`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(title)}</title>
<meta name="robots" content="noindex"><meta name="theme-color" content="#0a0a0a"><style>${STYLE}</style>${THEME_INIT}</head>
<body><div class="home">${headerHtml()}${accountPanelHtml()}<main class="home-wrap dl-main">${body}</main>${footerHtml()}</div>${THEME_WIRE}</body></html>`,
    { headers: { 'content-type': 'text/html; charset=utf-8' } })

/* ── the data ────────────────────────────────────────────────────────── */

type ListedAsset = { key: string; name: string; size: number; uploaded: Date | null }
type BucketRelease = { version: string; assets: ListedAsset[] }
type ReleaseView = {
  version: string
  tag: string
  date: string
  commits: number | null
  highlights: HistoryHighlight[]
  assets: ListedAsset[]
  latest: boolean
}

const listPrefix = async (
  bucket: R2Bucket,
  options: { prefix: string; delimiter?: string },
): Promise<{ objects: { key: string; size: number; uploaded: Date | null }[]; prefixes: string[] }> => {
  const objects: { key: string; size: number; uploaded: Date | null }[] = []
  const prefixes = new Set<string>()
  let cursor: string | undefined
  // Versioned keys are few; the page bound only guards a pathological bucket.
  for (let page = 0; page < 20; page++) {
    const result = await bucket.list({ ...options, cursor })
    for (const object of result.objects) {
      objects.push({ key: object.key, size: object.size, uploaded: object.uploaded ?? null })
    }
    for (const prefix of result.delimitedPrefixes ?? []) prefixes.add(prefix)
    if (!result.truncated) break
    cursor = result.cursor
  }
  return { objects, prefixes: [...prefixes] }
}

const compareVersions = (a: string, b: string) => {
  const pa = a.split('.').map(Number)
  const pb = b.split('.').map(Number)
  for (let i = 0; i < 3; i++) {
    if ((pa[i] ?? 0) !== (pb[i] ?? 0)) return (pa[i] ?? 0) - (pb[i] ?? 0)
  }
  return 0
}

/** Every `v<semver>/` prefix in the bucket is a downloadable release. A
 *  list failure degrades to the history-only view rather than a 500. */
const listReleases = async (env: DownloadsEnv): Promise<BucketRelease[]> => {
  if (!env.DOWNLOADS?.list) return []
  const { prefixes } = await listPrefix(env.DOWNLOADS, { prefix: 'v', delimiter: '/' })
  const releases = await Promise.all(
    prefixes.map(async (prefix) => {
      const { objects } = await listPrefix(env.DOWNLOADS!, { prefix })
      const version = prefix.replace(/^v/, '').replace(/\/$/, '')
      const assets = objects
        .filter((object) => OBJECT_KEY.test(object.key))
        .map((object) => ({
          key: object.key,
          name: object.key.split('/').pop() ?? object.key,
          size: object.size,
          uploaded: object.uploaded,
        }))
        .sort((a, b) => a.name.localeCompare(b.name))
      return { version, assets }
    }),
  )
  return releases.filter((release) => release.assets.length).sort((a, b) => compareVersions(b.version, a.version))
}

const newestUpload = (release: BucketRelease) =>
  release.assets.reduce<Date | null>(
    (best, asset) => (asset.uploaded && (!best || asset.uploaded > best) ? asset.uploaded : best),
    null,
  )

/** history.json supplies the "how it developed" notes for every tag;
 *  the bucket supplies the downloadable assets. Merged by version. */
const combinedReleases = async (env: DownloadsEnv, manifest: LatestManifest | null): Promise<ReleaseView[]> => {
  const [bucketReleases, history] = await Promise.all([
    listReleases(env).catch(() => []),
    historyManifest(env).catch(() => null),
  ])
  const byVersion = new Map(bucketReleases.map((release) => [release.version, release]))
  const versions = new Set<string>([
    ...bucketReleases.map((release) => release.version),
    ...(history?.releases ?? []).map((release) => release.version),
  ])
  const views = [...versions].map((version): ReleaseView => {
    const bucket = byVersion.get(version)
    const notes = history?.releases.find((release) => release.version === version)
    const upload = bucket ? newestUpload(bucket) : null
    const date =
      notes?.date ??
      (manifest?.version === version && manifest.released ? manifest.released : null) ??
      (upload ? upload.toISOString().slice(0, 10) : '—')
    return {
      version,
      tag: notes?.tag ?? `v${version}`,
      date,
      commits: typeof notes?.commits === 'number' ? notes.commits : null,
      highlights: Array.isArray(notes?.highlights) ? notes.highlights : [],
      assets: bucket?.assets ?? [],
      latest: manifest?.version === version,
    }
  })
  return views.sort((a, b) => compareVersions(b.version, a.version))
}

const assetLink = (asset: ListedAsset) =>
  `<a href="/${escapeHtml(asset.key)}">${escapeHtml(asset.name)}<span class="dl-size">${(asset.size / 1048576).toFixed(1)} MB</span></a>`

const releaseHtml = (release: ReleaseView) => {
  const latest = release.latest ? '<span class="dl-latest">latest</span>' : ''
  const meta = [
    release.date,
    release.commits !== null ? `${release.commits} commit${release.commits === 1 ? '' : 's'}` : null,
    release.tag ? `<a href="${REPO}/tree/${escapeHtml(release.tag)}" style="color:var(--home-ink-muted)">source</a>` : null,
  ]
    .filter(Boolean)
    .join(' · ')
  const highlights = release.highlights.length
    ? `<ul class="dl-highlights">${release.highlights
        .map((highlight) => {
          const label = `${highlight.sha ? `<span class="dl-sha">${escapeHtml(highlight.sha.slice(0, 7))}</span>` : ''}${escapeHtml(highlight.subject)}`
          return `<li>${highlight.url ? `<a href="${escapeHtml(highlight.url)}">${label}</a>` : label}</li>`
        })
        .join('')}</ul>`
    : ''
  const assets = release.assets.length
    ? `<ul class="dl-assets">${release.assets.map(assetLink).join('')}</ul>`
    : '<p class="dl-empty">No installer artifacts are published for this release.</p>'
  return `<article class="dl-release">
<div class="dl-release-head"><a class="dl-version" href="/v${escapeHtml(release.version)}">v${escapeHtml(release.version)}</a>${latest}</div>
<p class="dl-meta">${meta}</p>${highlights}${assets}
</article>`
}

const indexPage = async (env: DownloadsEnv, manifest: LatestManifest | null): Promise<Response> => {
  const releases = await combinedReleases(env, manifest)
  const current = manifest ? releases.find((release) => release.latest) : null
  const rows = manifest
    ? (['mac', 'windows', 'linux'] as const)
        .map((platform) => {
          const key = manifest.assets[platform]
          const name = key ? key.split('/').pop() : null
          return key && name
            ? `<span class="dl-shortcuts"><a href="/${escapeHtml(key)}">${platform}</a> · ${escapeHtml(name)}</span><br>`
            : ''
        })
        .join('')
    : '<span class="dl-empty">No release published yet.</span>'
  const hero = `<section class="dl-hero">
<h1 class="dl-title">${manifest ? `manorama v${escapeHtml(manifest.version)}` : 'manorama downloads'}</h1>
<p class="dl-lede">Native apps for macOS, Windows and Linux — the same gallery, on your desk. Every release stays here, with its notes.</p>
<p class="dl-eyebrow">desktop downloads</p>
<div class="dl-platforms">
${(['mac', 'windows', 'linux'] as const)
  .map((platform) => {
    const key = manifest?.assets[platform]
    return typeof key === 'string' && OBJECT_KEY.test(key)
      ? `<a class="home-btn${platform === 'mac' ? '' : ' home-btn-quiet'}" href="/${escapeHtml(key)}">${platform === 'mac' ? 'Download for macOS' : platform === 'windows' ? 'Download for Windows' : 'Download for Linux'}</a>`
      : ''
  })
  .join('')}
</div>
<p class="dl-eyebrow">mobile downloads</p>
<p class="dl-shortcuts">iPhone &amp; iPad — coming soon</p>
<p class="dl-shortcuts" style="margin-top:20px">Shortcuts: <a href="/mac">/mac</a> · <a href="/windows">/windows</a> · <a href="/linux">/linux</a> · <a href="/latest.json">/latest.json</a></p>
${rows ? `<p class="dl-shortcuts" style="margin-top:10px">${rows}</p>` : ''}
${current?.highlights.length ? `<p class="dl-latest-line">Latest: ${escapeHtml(current.highlights[0]!.subject)}</p>` : ''}
</section>`
  const history = releases.length
    ? `<section class="dl-history"><h2>Release history</h2>
<p class="dl-history-sub">Every tagged build, newest first — what changed, and the installers it shipped. The full record lives on <a href="${REPO}/releases" style="color:var(--home-ink-soft)">GitHub</a>.</p>
${releases.map(releaseHtml).join('')}</section>`
    : ''
  return page(`manorama downloads${manifest ? ` ${manifest.version}` : ''}`, hero + history)
}

const versionPage = async (env: DownloadsEnv, manifest: LatestManifest | null, version: string): Promise<Response | null> => {
  const releases = await combinedReleases(env, manifest)
  const release = releases.find((candidate) => candidate.version === version)
  if (!release) return null
  const latest = release.latest ? '<span class="dl-latest" style="margin-left:10px">latest</span>' : ''
  const body = `<section class="dl-hero">
<p class="dl-eyebrow"><a href="/" style="color:var(--home-ink-muted);text-decoration:none">← all releases</a></p>
<h1 class="dl-title">v${escapeHtml(release.version)}${latest}</h1>
<p class="dl-meta" style="font-size:13px">${release.date}${release.commits !== null ? ` · ${release.commits} commits` : ''}</p>
</section>
${releaseHtml(release).replace(/^<article[^>]*>|<\/article>$/g, '')}
<p style="margin-top:32px"><a class="home-btn home-btn-quiet" href="/">All releases</a></p>`
  return page(`manorama v${version}`, body)
}

const objectResponse = async (env: DownloadsEnv, key: string, head: boolean): Promise<Response> => {
  const object = await env.DOWNLOADS!.get(key)
  if (!object) return new Response('not found', { status: 404 })
  const headers = new Headers()
  object.writeHttpMetadata(headers)
  headers.set('etag', object.httpEtag)
  // Versioned keys never change; manifests and page assets are mutable and
  // stay short-lived.
  const cache = MANIFEST_PATHS.has(key) || ASSET_KEY.test(key)
    ? 'public, max-age=300'
    : 'public, max-age=31536000, immutable'
  headers.set('cache-control', cache)
  return new Response(head ? null : object.body, { headers })
}

export async function handleDownloads(request: Request, env: DownloadsEnv): Promise<Response> {
  if (!env.DOWNLOADS) return new Response('downloads are not configured', { status: 503 })
  if (request.method !== 'GET' && request.method !== 'HEAD') {
    return new Response('method not allowed', { status: 405, headers: { allow: 'GET, HEAD' } })
  }
  const url = new URL(request.url)
  const path = url.pathname.replace(/^\/+|\/+$/g, '')
  const head = request.method === 'HEAD'

  const manifest = await latestManifest(env)

  if (path === '') return indexPage(env, manifest)

  if (PLATFORMS.has(path)) {
    const key = manifest?.assets[path as keyof LatestManifest['assets']]
    if (typeof key !== 'string' || !OBJECT_KEY.test(key)) {
      return new Response('unknown platform or no release published', { status: 404 })
    }
    return Response.redirect(new URL(`/${key}`, url).toString(), 302)
  }

  const versionMatch = /^v(\d+\.\d+\.\d+)$/.exec(path)
  if (versionMatch) {
    const page = await versionPage(env, manifest, versionMatch[1]!)
    return page ?? new Response('not found', { status: 404 })
  }

  if (!MANIFEST_PATHS.has(path) && !OBJECT_KEY.test(path) && !ASSET_KEY.test(path)) {
    return new Response('not found', { status: 404 })
  }
  return objectResponse(env, path, head)
}
